# %% ../nbs/01_data_creator.ipynb 4
def one_hot(labels, n_classes=10):
    arr = torch.eye(n_classes)
    return arr[labels]


class MNIST(datasets.MNIST):
    def __init__(self, train, normalise=True, save_dir="../data", total_classes=10):
        self.total_classes = total_classes
        if normalise:
            transform = transforms.Compose(
                [
                    transforms.ToTensor(),
                    transforms.Normalize(
                        mean=(0.1307), std=(0.3081)
                    )
                ]
            )
        else:
            transform = transforms.Compose([transforms.ToTensor()])
        super().__init__(save_dir, download=True, train=train, transform=transform)

    def __getitem__(self, index):
        img, label = super().__getitem__(index)
        img = torch.flatten(img)
        label = one_hot(label, n_classes=self.total_classes)
        return img, label


# %% ../nbs/01_data_creator.ipynb 8
class FashionMNIST(datasets.FashionMNIST):
    def __init__(self, train, normalise=True, save_dir="../data", total_classes=10):
        self.total_classes = total_classes
        if normalise:
            transform = transforms.Compose(
                [
                    transforms.ToTensor(),
                    transforms.Normalize(
                        mean=(0.1307), std=(0.3081)
                    )
                ]
            )
        else:
            transform = transforms.Compose([transforms.ToTensor()])
        super().__init__(save_dir, download=True, train=train, transform=transform)

    def __getitem__(self, index):
        img, label = super().__getitem__(index)
        img = torch.flatten(img)
        label = one_hot(label, n_classes=self.total_classes)
        return img, label

# %% ../nbs/01_data_creator.ipynb 12
class CombinedMNIST(Dataset):
    """Combined MNIST and FashionMNIST dataset with 20 classes total.
    MNIST classes: 0-9
    FashionMNIST classes: 10-19
    """
    def __init__(self, train, normalise=True, save_dir="../data", label_compress = False, total_classes=20):
        self.mnist = MNIST(train=train, normalise=normalise, save_dir=save_dir, total_classes=total_classes)
        self.fashionmnist = FashionMNIST(train=train, normalise=normalise, save_dir=save_dir, total_classes=total_classes)
        self.mnist_len = len(self.mnist)
        self.fashion_len = len(self.fashionmnist)
        self.total_len = self.mnist_len + self.fashion_len
        self.label_compress = label_compress
        self.total_classes = total_classes
        
    def __len__(self):
        return self.total_len
    
    def __getitem__(self, index):
        if index < self.mnist_len:
            # Get from MNIST (classes 0-9)
            img, label = self.mnist[index]
            return img, label
        else:
            # Get from FashionMNIST (classes 10-19)
            img, label = self.fashionmnist[index - self.mnist_len]
            # Shift labels by 10 to make them classes 10-19
            label_idx = 10 if self.label_compress else torch.argmax(label).item() + 10
            label = one_hot(label_idx, n_classes=self.total_classes)
            return img, label

# %% ../nbs/01_data_creator.ipynb 16
class CIFAR10(datasets.CIFAR10):
    def __init__(self, train, normalise=True, save_dir="../data"):
        if normalise:
            transform = transforms.Compose(
                [
                    transforms.ToTensor(),
                    transforms.Normalize(
                        mean=(0.4914, 0.4822, 0.4465),
                        std=(0.2023, 0.1994, 0.2010)
                    )
                ]
            )
        else:
            transform = transforms.Compose([transforms.ToTensor()])
        super().__init__(save_dir, download=True, train=train, transform=transform)

    def __getitem__(self, index):
        img, label = super().__getitem__(index)
        img = torch.flatten(img)
        label = one_hot(label, n_classes=10)
        return img, label

# %% ../nbs/01_data_creator.ipynb 20
def preprocess_audio(waveform, sample_rate, target_sample_rate=16000, max_length=16000, normalise=True):
    """Preprocess audio waveform to standardized format."""
    # Resample if necessary
    if sample_rate != target_sample_rate:
        resampler = torchaudio.transforms.Resample(sample_rate, target_sample_rate)
        waveform = resampler(waveform)
    
    # Convert to mono if stereo
    if waveform.shape[0] > 1:
        waveform = torch.mean(waveform, dim=0, keepdim=True)
    
    # Pad or truncate to fixed length
    if waveform.shape[1] < max_length:
        padding = max_length - waveform.shape[1]
        waveform = torch.nn.functional.pad(waveform, (0, padding))
    else:
        waveform = waveform[:, :max_length]
    
    # Flatten the waveform
    waveform = torch.flatten(waveform)
    
    # Normalize if requested
    if normalise:
        std = waveform.std()
        if std > 1e-8:
            waveform = (waveform - waveform.mean()) / std
        else:
            waveform = waveform - waveform.mean()
    
    return waveform


def get_speech_classes():
    """Get standard speech commands classes."""
    # return ["yes", "no", "up", "down", "left", "right", "on", "off", "stop", "go", "backward", "silence", 'five']
    return ['backward', 'bed', 'bird', 'cat', 'dog', 'down', 'eight', 'five',
        'follow', 'forward', 'four', 'go', 'happy', 'house', 'learn',
        'left', 'marvin', 'nine', 'no', 'off', 'on', 'one', 'right',
        'seven', 'sheila', 'six', 'stop', 'three', 'tree', 'two', 'up',
        'visual', 'wow', 'yes', 'zero']

def label_to_onehot(label, classes):
    """Convert string label to one-hot encoding."""
    class_to_idx = {cls: idx for idx, cls in enumerate(classes)}
    
    if label in class_to_idx:
        label_idx = class_to_idx[label]
    else:
        print(f"Warning: label '{label}' not in known classes. Assigning to 'unknown'.")
        label_idx = class_to_idx["unknown"]
    
    return one_hot(torch.tensor(label_idx), n_classes=len(classes))


class SPEECHCOMMANDS(torchaudio.datasets.SPEECHCOMMANDS):
    def __init__(self, train, normalise=True, save_dir="../data", sample_rate=16000, max_length=16000):
        subset = "training" if train else "testing"
        super().__init__(save_dir, download=True, subset=subset)
        self.normalise = normalise
        self.sample_rate = sample_rate
        self.max_length = max_length
        self.classes = get_speech_classes()

    def __getitem__(self, index):
        waveform, sample_rate, label, speaker_id, utterance_number = super().__getitem__(index)
        
        # Preprocess audio
        waveform = preprocess_audio(
            waveform, sample_rate, self.sample_rate, self.max_length, self.normalise
        )
        
        # Convert label to one-hot
        label_onehot = label_to_onehot(label, self.classes)
        
        return waveform, label_onehot


