def get_speechcommands_loaders(batch_size, sample_rate=16000, max_length=16000):
    with open(f'../sub_path_idx/speechcommands_subset_idx_0.pkl', 'rb') as f:
        train_subset_idx = pickle.load(f)
    with open(f'../sub_path_idx/speechcommands_subset_idx_1.pkl', 'rb') as f:
        test_subset_idx = pickle.load(f)

    train_data = SPEECHCOMMANDS(train=True, normalise=True, sample_rate=sample_rate, max_length=max_length)
    train_data = Subset(train_data, train_subset_idx)
    test_data = SPEECHCOMMANDS(train=False, normalise=True, sample_rate=sample_rate, max_length=max_length)
    test_data = Subset(test_data, test_subset_idx)
    print(f'[CAVEAT] Only using subset of SpeechCommands dataset which has 10 classes with 1000 training samples and 100 test samples each.')
    train_loader = DataLoader(
        dataset=train_data,
        batch_size=batch_size,
        shuffle=True,
        drop_last=True
    )
    test_loader = DataLoader(
        dataset=test_data,
        batch_size=batch_size,
        shuffle=True,
        drop_last=True
    )
    return train_loader, test_loader


def get_combined_loaders(batch_size, label_compress = False, total_classes=20):
    train_data = CombinedMNIST(train=True, normalise=True, label_compress=label_compress, total_classes=total_classes)
    test_data = CombinedMNIST(train=False, normalise=True, label_compress=label_compress, total_classes=total_classes)
    train_loader = DataLoader(
        dataset=train_data,
        batch_size=batch_size,
        shuffle=True,
        drop_last=True
    )
    test_loader = DataLoader(
        dataset=test_data,
        batch_size=batch_size,
        shuffle=True,
        drop_last=True
    )
    return train_loader, test_loader

